/*
 * SPDX-License-Identifier: LGPL-2.0-or-later
 *
 * colorburst: clean-room replacement for upstream charset.h / byteio.h /
 * vnconv.h (all GPL-2.0-or-later upstream). ukengine.cpp includes charset.h for
 * a handful of things: the StdVnChar integer encoding, a couple of fold tables
 * (StdVnNoTone / StdVnRootChar), a tiny output-stream + charset object used by
 * writeOutput(), and (only on the macro path, which the PoC disables) VnConvert.
 *
 * We provide ONLY those pieces, and we make the single output charset emit
 * UTF-8 directly from the VnLexiName encoding — dropping the whole legacy
 * TCVN/VNI/VISCII conversion machinery. This severs the GPL data.cpp/charset.cpp
 * coupling without touching a line of the LGPL engine. See README.chromium.
 */
#ifndef __CHARSET_CONVERT_H
#define __CHARSET_CONVERT_H

#include <stdint.h>
#include <cstdio>  // FILE, used by mactab.h's file methods (unused in PoC)

typedef unsigned char UKBYTE;
typedef uint32_t StdVnChar;

// Sizes of the Vietnamese lexical alphabet. TOTAL_ALPHA_VNCHARS is the count of
// VnLexiName entries (vnl_A..vnl_z); TOTAL_VNCHARS leaves room for the handful
// of "special western" codes the engine appends past vnl_lastChar.
#define TOTAL_ALPHA_VNCHARS 198
#define TOTAL_VNCHARS 213

// StdVnChar = VnStdCharOffset + VnLexiName (for Vietnamese symbols); values
// below the offset are raw ISO/keycode bytes passed through untouched.
const StdVnChar VnStdCharOffset = 0x10000;
const StdVnChar INVALID_STD_CHAR = 0xFFFFFFFF;

// Charset ids. ukengine.cpp compares m_pCtrl->charsetId against these; we only
// ever run it as CONV_CHARSET_XUTF8. The others just need distinct values so
// the legacy branches are never taken.
#define CONV_CHARSET_UNICODE 0
#define CONV_CHARSET_UNIDECOMPOSED 4
#define CONV_CHARSET_UNI_CSTRING 6
#define CONV_CHARSET_VNSTANDARD 7
#define CONV_CHARSET_VIQR 10
#define CONV_CHARSET_XUTF8 12

#define VNCONV_OUT_OF_MEMORY 1

// clean-room fold tables + codepoint table (generated by gen_tables.py).
extern int StdVnNoTone[];
extern int StdVnRootChar[];
extern const unsigned int UkVnLexiToUnicode[];
extern const int UkVnLexiCount;
// rebuildChar() maps a root VnLexiName to its plain ASCII letter; that is just
// the codepoint of the (always-ASCII) root, so we alias our codepoint table.
extern const unsigned int *const UnicodeTable;

// Minimal output byte stream. Counts bytes even when buf==nullptr/size==0 so
// getSeqSteps()'s dry-run measurement keeps working.
class StringBOStream {
public:
    StringBOStream(unsigned char *buf, int size) : m_buf(buf), m_max(size), m_n(0) {}
    void putB(unsigned char c) {
        if (m_buf && m_n < m_max)
            m_buf[m_n] = c;
        m_n++;
    }
    int getOutBytes() const { return m_n; }

private:
    unsigned char *m_buf;
    int m_max;
    int m_n;
};

// Single UTF-8 output charset. putChar() turns one StdVnChar into UTF-8 bytes.
class VnCharset {
public:
    void startOutput() {}
    // Returns 1 on success (matches upstream's non-zero == ok convention used by
    // writeOutput()).
    int putChar(StringBOStream &os, StdVnChar stdChar, int &outLen);
};

class VnCharsetLib {
public:
    VnCharset *getVnCharset(int /*charsetId*/) { return &m_utf8; }

private:
    VnCharset m_utf8;
};

extern VnCharsetLib VnCharsetLibObj;

// Case fold on StdVnChar. Vietnamese symbols are laid out upper(even)/lower(odd)
// in pairs; ASCII falls back to C toupper/tolower.
StdVnChar StdVnToUpper(StdVnChar ch);
StdVnChar StdVnToLower(StdVnChar ch);

// Only reached on the macro-expansion path, which the PoC leaves disabled.
int VnConvert(int inCharset, int outCharset, UKBYTE *input, UKBYTE *output,
              int *inLen, int *maxOutLen);

#endif
